insert into public.catalog_destinations (id, realm, lore, name, original_name, tagline, group_name, location, era, latitude, longitude, overview, hidden, updated_at, updated_by) values
  ('giza', 'real', 'fact', '기자 피라미드', 'Giza Pyramid Complex', '고대 7대 불가사의 중 유일하게 남은 곳', '아프리카', '이집트 기자', '기원전 26세기', 29.9761, 31.1328, '고왕국 제4왕조의 쿠푸 왕 무덤인 대피라미드를 중심으로 세 기의 큰 피라미드와 스핑크스가 모여 있습니다. 대피라미드는 지어질 때 약 146.6m였고 흰 석회암 외장이 뜯겨 나가 지금은 약 138.5m입니다. 중세 링컨 대성당이 세워지기 전까지 3800년 넘게 세계에서 가장 높은 건축물이었습니다.', false, now(), null),
  ('karnak', 'real', 'fact', '카르나크 신전', 'Karnak Temple Complex', '2000년에 걸쳐 증축된 거대한 돌기둥의 숲', '아프리카', '이집트 룩소르', '중왕국~프톨레마이오스 왕조', 25.7183, 32.6583, '옛 수도 테베의 북쪽에 아문 대신전과 무트·몬투 신전이 모인 세계 최대급 종교 시설입니다. 중왕국의 작은 신전에서 시작해 약 2000년 동안 왕들이 앞다투어 늘렸고, 현재 남은 건축물은 대부분 신왕국 시대의 것입니다.', false, now(), null),
  ('abu-simbel', 'real', 'fact', '아부심벨 신전', 'Abu Simbel Temples', '댐을 피해 산째로 옮겨진 람세스 2세의 신전', '아프리카', '이집트 아스완 남쪽', '기원전 13세기', 22.3369, 31.6256, '람세스 2세가 누비아 지방에 위세를 과시하려고 바위산을 깎아 만든 신전입니다. 오랫동안 모래에 묻혔다가 1813년 부르크하르트가 알아보고 1817년 벨초니가 입구를 열었습니다. 1960년대 아스완 하이 댐 건설로 수몰될 위기에 놓이자 국제 협력으로 조각조각 잘라 더 높은 곳에 다시 세웠습니다.', false, now(), null),
  ('great-zimbabwe', 'real', 'fact', '그레이트 짐바브웨', 'Great Zimbabwe', '사하라 이남 최대의 석조 도시 유적', '아프리카', '짐바브웨 마스빙고', '13~15세기', -20.2667, 30.9333, '쇼나족이 금과 상아, 구리 무역으로 번영하며 쌓은 석조 도시입니다. 최대 높이 11m의 벽을 회반죽 없이 쌓은 그레이트 인클로저가 대표적입니다. 중국 도자기와 페르시아 유리구슬 조각이 출토되어 인도양 교역망에 닿아 있었음을 보여 줍니다.', false, now(), null),
  ('carthage', 'real', 'history', '카르타고', 'Carthage', '로마와 지중해를 다툰 페니키아의 도시', '아프리카', '튀니지 튀니스 근교', '기원전 9세기~로마 시대', 36.8528, 10.3233, '페니키아인이 세워 지중해 패권을 놓고 로마와 포에니 전쟁을 벌인 도시입니다. 로마가 철저히 파괴한 탓에 페니키아 시대 유적은 일부만 남았고, 지금 볼 수 있는 유적은 대부분 그 위에 다시 지은 로마 시대의 것입니다.', false, now(), null),
  ('machu-picchu', 'real', 'fact', '마추픽추', 'Machu Picchu', '구름 위에 숨은 잉카의 도시', '아메리카', '페루 쿠스코주', '15세기 후반', -13.1633, -72.5456, '해발 약 2,437m 능선에 있는 잉카 유적으로, 파차쿠티와 투팍 잉카 유판키 시대에 황실 휴양지이자 대피처로 지어졌다고 봅니다. 약 750명이 살다가 1530년대 무렵 버려졌고, 1911년 하이럼 빙엄이 현지인의 안내로 확인해 세상에 널리 알려졌습니다.', false, now(), null),
  ('chichen-itza', 'real', 'history', '치첸이트사', 'Chichén Itzá', '춘분에 뱀이 내려오는 마야의 피라미드', '아메리카', '멕시코 유카탄', '750년경~13세기', 20.6831, -88.5686, '이름은 이트사족의 우물 입구라는 뜻으로, 제물을 바치던 세노테와 관련됩니다. 남부 마야 도시들이 쇠퇴한 뒤 유민을 흡수하며 후고전기의 지역 강국으로 성장했습니다. 춘분과 추분 해질녘 엘 카스티요 계단에 뱀 그림자가 나타나는 것으로 유명합니다.', false, now(), null),
  ('tikal', 'real', 'fact', '티칼', 'Tikal', '정글 위로 솟은 고전기 마야의 수도', '아메리카', '과테말라 페텐', '200~900년 전성기', 17.2219, -89.6236, '마야어로 약스 무탈이라 불린 대도시로, 전성기에 약 10만 명이 살며 칼라크물과 패권을 다투고 테오티우아칸과도 교류했습니다. 기후 변화와 기근으로 10세기 무렵 몰락해 밀림에 묻혔다가 1848년 무렵 재발견되었고 1979년 세계유산이 되었습니다.', false, now(), null),
  ('teotihuacan', 'real', 'history', '테오티우아칸', 'Teotihuacan', '신들의 도시라 불린 메소아메리카의 로마', '아메리카', '멕시코 멕시코주', '1~6세기 전성기', 19.6925, -98.8439, '멕시코시티 북동쪽 약 50km, 해발 2,300m에 자리한 고대 도시입니다. 인근 쿠이쿠일코의 난민과 지식이 흘러들며 커졌고 450년 무렵 인구가 약 20만에 달했습니다. 도시를 세운 사람들이 누구인지는 아직 뚜렷이 밝혀지지 않았습니다.', false, now(), null),
  ('nazca', 'real', 'fact', '나스카 지상화', 'Líneas de Nazca', '하늘에서만 온전히 보이는 사막의 그림', '아메리카', '페루 이카주', '기원전 500년~기원후 500년', -14.6975, -75.135, '리마 남쪽 약 400km 사막에 거미·벌새·원숭이 같은 그림과 직선, 소용돌이가 새겨져 있습니다. 큰 그림은 300m에 이릅니다. 수십 년을 연구한 마리아 라이헤는 천문 용도를 주장했고, 최근에는 AI로 새 그림 수백 개를 더 찾아냈습니다.', false, now(), null),
  ('rapa-nui', 'real', 'history', '라파누이(이스터섬)', 'Rapa Nui', '태평양 끝에서 섬을 지켜 온 모아이', '오세아니아', '칠레령 폴리네시아', '13~17세기 모아이 제작', -27.1258, -109.2769, '칠레 본토에서 약 3,510km 떨어진 화산섬으로, 원주민은 라파누이라 부릅니다. 1722년 부활절에 네덜란드인이 도착해 이스터섬이라는 이름이 붙었습니다. 섬 곳곳의 거대한 모아이를 어떻게 옮겨 세웠는지는 지금도 여러 가설이 있습니다.', false, now(), null),
  ('angkor-wat', 'real', 'history', '앙코르 와트', 'Angkor Wat', '해가 탑 끝을 지나도록 설계된 크메르의 사원', '아시아', '캄보디아 시엠립', '12세기', 13.4125, 103.8667, '크메르 제국의 수리야바르만 2세가 힌두교 사원으로 세웠고 뒤에 불교 사원이 되었습니다. 축을 정동쪽에서 약간 틀어, 춘분과 추분 서쪽 참배로에서 보면 해가 중앙탑 끝에서 떠오릅니다. 중앙 성소는 약 65m 높이이며 계단이 매우 가파릅니다.', false, now(), null),
  ('bagan', 'real', 'fact', '바간', 'Bagan', '평원을 메운 수천 개의 불탑', '아시아', '미얀마 만달레이 지방', '11~13세기', 21.1725, 94.86, '에야와디강 동쪽 평원에 약 5천 개의 불탑과 사원이 남아 있습니다. 아노라타 왕이 몬족의 문화를 받아들인 뒤 바간 왕조의 수도로 번성했고, 12~13세기에는 세계적인 불교 연구 중심지였습니다. 1287년 몽골 원나라의 침공으로 급격히 쇠락했습니다.', false, now(), null),
  ('borobudur', 'real', 'fact', '보로부두르', 'Borobudur', '돌로 쌓아 올린 세계 최대의 입체 만다라', '아시아', '인도네시아 중부 자바', '8~9세기', -7.608, 110.204, '사일렌드라 왕조가 세운 세계 최대 규모의 불교 유적으로, 504개의 불상과 2,672개의 부조 패널로 장식되어 있습니다. 왕국의 중심이 동쪽으로 옮겨 가며 잊혔고, 1814년 영국 총독 래플스가 조사를 시작하면서 다시 알려졌습니다.', false, now(), null),
  ('petra', 'real', 'history', '페트라', 'Petra', '붉은 사암을 깎아 만든 나바테아의 도시', '아시아', '요르단 와디무사', '기원전 4세기경~로마 시대', 30.3285, 35.4444, '유목민 나바테아인이 사암 절벽을 파내어 만든 산악 도시로, 그들은 레켐이라 불렀습니다. 페트라는 바위를 뜻하는 그리스어이고 붉은빛 때문에 장미의 도시로도 불립니다. 좁은 협곡 시크를 지나면 거대한 알카즈네가 나타납니다.', false, now(), null),
  ('gobekli-tepe', 'real', 'fact', '괴베클리 테페', 'Göbekli Tepe', '농경보다 먼저 세워진 인류 최초의 신전 후보', '아시아', '튀르키예 샨르우르파', '기원전 약 9600년', 37.2236, 38.9217, '배불뚝이 언덕이라는 뜻의 해발 760m 언덕에 T자 돌기둥 200개 이상이 원을 이루고 있습니다. 가장 큰 기둥은 약 5.5m입니다. 약 11,700년 전으로 측정되어 피라미드보다 7천 년가량 앞섭니다. 1994년부터 클라우스 슈미트가 본격적으로 발굴했고 2018년 세계유산이 되었습니다.', false, now(), null),
  ('ephesus', 'real', 'history', '에페소스', 'Ephesus', '켈수스 도서관이 남은 소아시아의 대도시', '아시아', '튀르키예 셀축', '기원전 9세기경~비잔티움 시대', 37.9411, 27.3419, '이오니아인이 세우고 로마 시대에 소아시아의 중심 도시로 번성해 인구가 약 25만에 이르렀다고 추정합니다. 고대 7대 불가사의인 아르테미스 신전이 있던 곳이자 초기 기독교의 일곱 교회 중 하나입니다. 강에서 내려온 토사로 항구가 메워지면서 쇠퇴했습니다.', false, now(), null),
  ('terracotta', 'real', 'history', '병마용', '兵馬俑', '황제를 지키려 땅에 묻힌 흙의 군대', '아시아', '중국 산시성 시안', '기원전 3세기', 34.385, 109.2731, '진시황릉 주변에서 발굴된 실물 크기의 병사와 말 토용입니다. 《사기》는 무덤에 수은으로 강과 바다를 만들었다고 전합니다. 병마용갱을 비롯한 일부만 발굴되었고, 봉분 자체는 기술과 보존 문제로 아직 손대지 않았습니다.', false, now(), null),
  ('hampi', 'real', 'history', '함피', 'Hampi', '바위 언덕에 남은 비자야나가르의 왕도', '아시아', '인도 카르나타카', '14~16세기', 15.3344, 76.4622, '퉁가바드라강 남쪽 바위 언덕에 펼쳐진 비자야나가르 제국의 수도입니다. 1500년 무렵 북경 다음가는 대도시였다고 전합니다. 1565년 탈리코타 전투 뒤 약탈로 폐허가 되었고, 1986년 세계유산이 되었습니다.', false, now(), null),
  ('gyeongju', 'real', 'history', '경주 역사유적지구', 'Gyeongju Historic Areas', '신라 천 년의 왕도를 걷는 하루', '아시아', '대한민국 경상북도 경주', '기원전 1세기~10세기', 35.8347, 129.219, '남산, 월성, 대릉원, 황룡사, 산성의 다섯 지구에 52개 문화유산이 모여 2000년 세계유산이 되었습니다. 불국사와 석굴암은 별도의 세계유산이지만 같은 도시에 있어 함께 돌아보기 좋습니다.', false, now(), null),
  ('colosseum', 'real', 'fact', '콜로세움', 'Colosseo', '로마의 함성이 남은 최대의 원형 경기장', '유럽', '이탈리아 로마', '서기 80년경', 41.8903, 12.4922, '7~8년의 공사 끝에 80년 무렵 완공된, 로마에서 가장 큰 원형 경기장입니다. 검투사 경기와 공연이 열렸습니다. 이름과 달리 정확한 원형이 아니라 타원형이며, 원래 콜로세움은 로마 도심의 이 경기장만 가리킵니다.', false, now(), null),
  ('pompeii', 'real', 'fact', '폼페이', 'Pompeii', '화산재 아래 멈춘 로마의 하루', '유럽', '이탈리아 캄파니아', '서기 79년 매몰', 40.75, 14.4861, '포도주 교역과 귀족 휴양지로 번성하던 도시가 베수비오 화산 폭발로 약 18시간 만에 잿더미에 덮였습니다. 1592년 운하 공사 중 흔적이 드러났고, 이후 발굴로 벽화와 빵집, 거리가 당시 모습 그대로 나타났습니다.', false, now(), null),
  ('acropolis', 'real', 'history', '아테네 아크로폴리스', 'Acropolis of Athens', '파르테논이 서 있는 도시의 언덕', '유럽', '그리스 아테네', '기원전 5세기 전성기', 37.9717, 23.7261, '높다는 뜻의 아크로와 도시를 뜻하는 폴리스가 합쳐진 말로, 성채와 신전이 모인 폴리스의 핵심 구역입니다. 아테네의 언덕에는 파르테논 신전, 에레크테이온, 프로필라이아 등이 모여 있어 시내 어디서나 보입니다.', false, now(), null),
  ('knossos', 'real', 'history', '크노소스 궁전', 'Knossos', '미궁 전설이 시작된 미노스 문명의 궁전', '유럽', '그리스 크레타섬', '기원전 1900~1350년경', 35.2981, 25.1631, '중앙 정원을 둘러싸고 1000개가 넘는 방이 얽힌 미노스 문명의 궁전으로, 미노타우로스와 미궁 신화의 무대가 되었습니다. 지진으로 무너진 뒤 기원전 1700년경 다시 지었습니다. 현재 모습에는 20세기 초 아더 에번스가 복원한 부분이 많이 섞여 있습니다.', false, now(), null),
  ('stonehenge', 'real', 'history', '스톤헨지', 'Stonehenge', '하지의 해를 맞이하는 평원의 거석', '유럽', '영국 잉글랜드 솔즈베리 평원', '기원전 3000~1500년경', 51.1789, -1.8261, '폭 6m 도랑으로 둘러싸인 지름 약 98m 원형 터에 거석을 세운 유적입니다. 터는 기원전 8천 년 무렵부터 쓰였고 세 단계에 걸쳐 건설되었습니다. 바깥 사르센 원의 돌 30개 가운데 지금은 17개만 남아 있습니다.', false, now(), null),
  ('avalon', 'fantasy', 'legend', '아발론', 'Avalon', '상처 입은 아더왕이 쉬러 간 사과의 섬', '켈트·아더왕', '서쪽 바다 너머', '12세기 문헌 등장', 51.1442, -2.6986, '사과를 뜻하는 켈트어에서 이름이 나온 낙원의 섬입니다. 몬머스의 제프리는 아홉 자매가 다스리는 곳으로 그렸고, 맏이 모르겐이 마지막 전투에서 다친 아더왕을 맞아 치료합니다. 엑스칼리버가 벼려진 곳으로도 전해집니다.', false, now(), null),
  ('camelot', 'fantasy', 'legend', '카멜롯', 'Camelot', '원탁의 기사들이 모인 아더왕의 성', '켈트·아더왕', '브리튼 어딘가', '12세기 후반 문헌 등장', 51.0236, -2.5314, '아더왕 왕국의 수도이자 성의 이름입니다. 뿌리인 웨일스 신화에는 없는 지명으로, 12세기 프랑스 시인 크레티앵 드 트루아의 《수레의 기사 랜슬롯》에서 처음 등장한 뒤 영국으로 거꾸로 들어왔습니다.', false, now(), null),
  ('tir-na-nog', 'fantasy', 'myth', '티르 나 노그', 'Tír na nÓg', '늙지 않는 젊음의 땅', '켈트·아더왕', '아일랜드 서쪽 바다 너머', '아일랜드 신화', 53.4, -10.23, '아일랜드 신화에서 젊음의 땅이라 불리는 낙원입니다. 영웅 오신은 요정 니아브를 따라 이곳에 가 3년처럼 지냈지만, 돌아와 보니 세상은 300년이 흘러 있었고 땅에 발이 닿자 단숨에 늙어 버렸습니다.', false, now(), null),
  ('arcadia', 'fantasy', 'myth', '아르카디아', 'Arkadia', '목신 판이 노니는 목가적 이상향', '그리스·로마', '그리스 펠로폰네소스 중앙', '고대 그리스~르네상스', 37.5089, 22.3794, '펠로폰네소스 반도 한가운데 실제로 있는 산악 지방에서 출발한 이상향입니다. 산이 많고 양치기가 평화롭게 사는 땅으로 알려졌고 목신 판의 영토로도 그려졌습니다. 시간이 흐르며 때 묻지 않은 자연을 뜻하는 시어가 되었습니다.', false, now(), null),
  ('atlantis', 'fantasy', 'legend', '아틀란티스', 'Atlantis', '하룻밤 만에 가라앉은 해양 제국', '그리스·로마', '헤라클레스의 기둥 너머', '기원전 4세기 플라톤 저술', 35.97, -5.6, '플라톤이 《티마이오스》와 《크리티아스》에서 처음 언급한 섬이자 도시입니다. 이름은 왕의 조상인 아틀라스에게서 왔습니다. 흔히 대륙으로 알려졌지만 플라톤은 큰 섬이라고 썼습니다. 다른 기록으로 검증되지 않아 허구이거나 산토리니 재난이 부풀려진 이야기로 봅니다.', false, now(), null),
  ('elysion', 'fantasy', 'myth', '엘리시온', 'Elysion', '영웅과 의인이 머무는 축복의 들판', '그리스·로마', '세상의 서쪽 끝', '호메로스 시대~', 38.0414, 23.5383, '고대 그리스의 사후 낙원입니다. 처음에는 신과 인연이 있는 영웅만 갈 수 있었지만 후대로 올수록 선한 삶을 산 사람까지 넓어졌습니다. 그곳에서는 생전에 즐기던 일을 평화롭게 이어 갑니다. 파리의 샹젤리제 거리도 이 이름에서 왔습니다.', false, now(), null),
  ('olympus', 'fantasy', 'myth', '올림포스', 'Olympos', '구름 위에 있는 열두 신의 궁전', '그리스·로마', '그리스 테살리아·마케도니아 경계', '그리스 신화', 40.0856, 22.3586, '그리스 신화에서 제우스와 올림포스 신들이 사는 곳입니다. 이름의 뿌리는 뚜렷하지 않습니다. 신화의 궁전은 상상이지만 같은 이름의 산은 그리스에서 가장 높은 실제 산이라 등산으로 정상에 설 수 있습니다.', false, now(), null),
  ('thule', 'fantasy', 'legend', '툴레', 'Thule', '해가 지지 않는 세상의 북쪽 끝', '북유럽', '브리튼에서 북쪽으로 6일 항해', '기원전 4세기', 62, -6.9, '마실리아의 항해자 피테아스가 기록한 세상 북쪽 끝의 땅입니다. 스코틀랜드에서 북쪽으로 6일을 가면 바다가 얼어붙고 해가 지지 않는다고 했습니다. 이후 세상의 끝을 뜻하는 울티마 툴레라는 표현이 퍼졌습니다.', false, now(), null),
  ('asgard', 'fantasy', 'myth', '아스가르드', 'Ásgarðr', '무지개다리 너머 아사 신족의 나라', '북유럽', '세계수 위쪽', '13세기 에다 기록', 59.8977, 17.6345, '이름은 아사 신족의 울타리라는 뜻입니다. 인간 세계 미드가르드와 무지개다리 비프로스트로 이어지고, 에다는 12개의 성채를 나열합니다. 오딘이 모은 전사들이 머무는 발할라도 이곳에 있습니다. 라그나로크로 무너진 뒤 다음 세대 신들이 다시 세운다고 합니다.', false, now(), null),
  ('utopia', 'fantasy', 'legend', '유토피아', 'Utopia', '어디에도 없는 곳이라는 이름의 섬', '근대 문학', '신대륙 너머의 섬', '1516년', 51.2194, 4.4025, '토머스 모어가 라틴어로 쓴 책의 섬입니다. 없다는 뜻의 우(ou)와 장소 토포스를 합친 이름으로, 사유재산이 없는 이상 사회를 그려 당대 잉글랜드를 꼬집었습니다. 이 단어는 지금 이상향을 뜻하는 말로 굳어졌습니다.', false, now(), null),
  ('shangri-la', 'fantasy', 'legend', '샹그릴라', 'Shangri-La', '히말라야 어딘가에 숨은 불로의 계곡', '동양', '티베트 고원의 숨겨진 계곡', '1933년', 27.8257, 99.7065, '제임스 힐턴의 소설 《잃어버린 지평선》에 나온 낙원으로, 영화가 흥행하며 이상향을 뜻하는 일반 명사가 되었습니다. 힐턴은 리장에 머문 식물학자 조지프 로크의 내셔널 지오그래픽 글에서 영감을 얻었다고 합니다.', false, now(), null),
  ('shambhala', 'fantasy', 'myth', '샴발라', 'Śambhala', '말세에 세상을 구하러 올 숨은 왕국', '동양', '티베트 깊숙한 곳', '11세기 경전', 29.6525, 91.1175, '티베트 불교에서 전하는 현자들의 이상향입니다. 여덟 꽃잎 모양의 분지에 나라와 도시들이 있고 사람들은 병과 굶주림, 다툼 없이 산다고 합니다. 세상이 전쟁과 탐욕으로 타락하면 샴발라의 왕이 나타나 다스린다고 합니다.', false, now(), null),
  ('sumeru', 'fantasy', 'myth', '수미산', 'Sumeru', '세계의 중심에 솟은 우주의 산', '동양', '우주의 한가운데', '고대 인도', 31.0667, 81.3125, '인도 신화에서 비롯해 불교와 힌두교가 받아들인 상상 속 성산입니다. 불교 우주관에서는 세계의 중앙에 있고 바다 위아래로 각각 8만 유순, 합쳐 16만 유순 높이라고 합니다. 티베트 불교는 이를 카일라스산과 동일시하지만 반론도 있습니다.', false, now(), null),
  ('peach-blossom', 'fantasy', 'legend', '무릉도원', '武陵桃源', '복사꽃 숲 끝 동굴 너머의 마을', '동양', '중국 무릉의 어느 시내 위쪽', '5세기', 28.9, 111.48, '도연명의 《도화원기》에 나오는 별천지입니다. 무릉의 어부가 복사꽃 숲을 지나 동굴을 빠져나가자 진나라의 난을 피해 온 사람들이 바깥 세월을 잊고 살고 있었습니다. 돌아간 뒤 다시 찾으려 했으나 끝내 길을 찾지 못했습니다.', false, now(), null),
  ('penglai', 'fantasy', 'myth', '봉래산', '蓬萊山', '불사약이 있다는 동쪽 바다의 신선 섬', '동양', '동쪽 바다 너머', '전국시대~진한', 37.8269, 120.7531, '방장산, 영주산과 함께 삼신산으로 불립니다. 선인이 살고 불사의 약이 있으며 금은 궁전이 구름처럼 보이지만 다가가면 풍랑에 막힌다고 합니다. 진시황이 서불을 보내 약을 구하게 한 이야기가 유명하고, 금강산의 여름 이름도 여기서 왔습니다.', false, now(), null),
  ('kunlun', 'fantasy', 'myth', '곤륜산', '崑崙山', '서왕모가 불사약을 지키는 서쪽 끝의 산', '동양', '중국 대륙 서쪽 끝', '《산해경》 시대', 36, 84, '도교에서 신선이 산다고 믿는 산입니다. 하늘에 닿을 만큼 높고 귀한 옥이 나며 불사의 강이 흐르고, 불로불사약의 주인 서왕모가 머문다고 합니다. 티베트 고원 북쪽의 실제 쿤룬산맥과 이름을 나눕니다.', false, now(), null),
  ('ieodo', 'fantasy', 'legend', '이어도', '離於島', '돌아오지 못한 이들이 산다는 제주의 섬', '동양', '제주 남서쪽 바다', '제주 민간 전승', 32.1229, 125.1824, '제주 민간에서 바다에 나가 돌아오지 못한 이들이 사는 곳으로 전해 온 전설의 섬입니다. 현실에도 이 이름이 붙은 수중 암초가 있는데, 마라도에서 남서쪽으로 149km 떨어져 있고 정상이 수면 아래 4.6m에 잠겨 있습니다. 파도가 칠 때만 드러납니다.', false, now(), null),
  ('takamagahara', 'fantasy', 'myth', '다카마가하라', '高天原', '아마테라스가 다스리는 하늘의 들판', '동양', '하늘 위', '8세기 기록', 32.705, 131.301, '《고사기》와 《일본서기》에 나오는 하늘 신들의 세계입니다. 최초의 신이 나타난 뒤 태양의 여신 아마테라스가 다스립니다. 스사노오는 이곳에서 쫓겨나고 니니기는 지상을 다스리려 내려갑니다.', false, now(), null),
  ('el-dorado', 'fantasy', 'legend', '엘도라도', 'El Dorado', '콘키스타도르를 삼킨 황금의 땅', '신대륙 전설', '남아메리카 어딘가', '16세기', 4.9775, -73.7747, '스페인어로 금을 입힌 것이라는 뜻입니다. 원래는 몸에 금가루를 바르고 호수에 제물을 바친 무이스카의 족장을 가리켰지만 온통 금으로 된 도시 이야기로 부풀었습니다. 수많은 정복자가 이 소문을 좇아 밀림으로 들어가 돌아오지 못했습니다.', false, now(), null),
  ('cibola', 'fantasy', 'legend', '시볼라의 일곱 도시', 'Seven Cities of Cibola', '코로나도를 북쪽으로 이끈 소문', '신대륙 전설', '북아메리카 남서부', '16세기', 34.93, -108.98, '중세 이베리아의 일곱 주교가 대서양 너머에 세웠다는 일곱 도시 전설이 신대륙의 황금 소문과 합쳐진 이야기입니다. 1540년 코로나도 원정대가 찾아갔지만 그곳에 있던 것은 황금 도시가 아니라 주니족의 흙벽 마을이었습니다.', false, now(), null),
  ('eden', 'fantasy', 'myth', '에덴 동산', 'Garden of Eden', '네 강이 흘러나간 최초의 낙원', '중동·이집트', '동방의 에덴', '구약 《창세기》', 31.0158, 47.4306, '《창세기》에서 신이 처음 지은 사람을 두었다는 동산입니다. 동산에서 흘러나온 강이 비손, 기혼, 티그리스, 유프라테스의 네 갈래로 나뉜다고 적혀 있습니다. 선악을 알게 하는 나무의 열매를 먹은 아담과 하와는 이곳에서 쫓겨나고, 동쪽 입구는 그룹과 불칼이 지킵니다.', false, now(), null),
  ('dilmun', 'fantasy', 'myth', '딜문', 'Dilmun', '수메르 신화가 노래한 깨끗하고 밝은 땅', '중동·이집트', '페르시아만', '수메르 신화', 26.2336, 50.5206, '수메르의 시 〈엔키와 닌후르사그〉에서 깨끗하고 밝은 땅으로 그려지는 곳입니다. 물의 신 엔키가 단물을 끌어와 이 땅을 기름지게 하고, 대지의 여신 닌후르사그가 기른 여덟 가지 풀을 엔키가 먹으면서 이야기가 벌어집니다. 길가메시 서사시에서 홍수의 생존자 우트나피쉬팀이 영생을 얻어 사는 곳으로 보기도 합니다.', false, now(), null),
  ('aaru', 'fantasy', 'myth', '아아루', 'Sekhet-Aaru', '오시리스가 다스리는 갈대의 들판', '중동·이집트', '해가 뜨는 동쪽 하늘', '고대 이집트', 25.7283, 32.6014, '고대 이집트 사람들이 심판을 통과한 영혼이 간다고 믿은 낙원으로, 갈대의 들판이라는 뜻입니다. 죽은 이의 심장을 진리의 깃털과 저울에 달아 통과하면 이곳에 이릅니다. 나일강 가처럼 물길이 흐르고 보리와 밀이 사람 키보다 크게 자라, 살아 있을 때처럼 밭을 갈며 영원히 지낸다고 했습니다.', false, now(), null),
  ('hades', 'fantasy', 'myth', '하데스의 명계', 'Hades', '스틱스강 너머 죽은 이들의 나라', '그리스·로마', '땅 아래', '기원전 8세기 문헌', 39.2362, 20.5345, '그리스 신화에서 죽은 이들이 가는 땅 아래 세계로, 다스리는 신의 이름을 따 하데스라고 부릅니다. 뱃사공 카론이 뱃삯을 받고 죽은 이를 건네주며, 머리 셋 달린 개 케르베로스가 문을 지킵니다. 오디세우스는 예언자 테이레시아스의 혼에게 길을 묻기 위해 이곳을 찾아갑니다.', false, now(), null),
  ('valhalla', 'fantasy', 'myth', '발할라', 'Valhöll', '오딘이 전사한 영웅을 모으는 전당', '북유럽', '아스가르드', '13세기 기록', 49.0315, 12.2241, '북유럽 신화에서 오딘이 다스리는 아스가르드의 큰 전당입니다. 발키리가 싸움터에서 고른 전사들이 에인헤랴르가 되어 이곳에서 낮에는 겨루고 밤에는 잔치를 엽니다. 〈그림니르의 노래〉는 문이 540개이고 문마다 800명이 나와 세상의 마지막 싸움 라그나로크에 나선다고 노래합니다.', false, now(), null),
  ('yomi', 'fantasy', 'myth', '요미노쿠니', '黄泉国', '이자나미가 머무는 어둠의 나라', '동양', '땅 아래', '8세기 기록', 35.4276, 133.1621, '일본 신화의 저승입니다. 이자나기는 죽은 아내 이자나미를 데리러 갔다가, 보지 말라는 약속을 어기고 썩어 가는 모습을 보고 달아납니다. 쫓아오는 저승의 군세에게 복숭아를 던져 물리치고, 산 자와 죽은 자의 경계인 요모쓰히라사카를 큰 바위로 막습니다.', false, now(), null),
  ('xibalba', 'fantasy', 'myth', '시발바', 'Xibalba', '쌍둥이 영웅이 공놀이로 이긴 공포의 저승', '신대륙 전설', '땅 아래', '16세기 기록', 17.13, -88.8658, '마야 키체족의 신화집 《포폴 부》에 나오는 저승으로, 공포의 장소라는 뜻입니다. 죽음의 군주들이 다스리며 어둠, 칼날, 추위, 재규어, 박쥐의 집 같은 시험장이 있습니다. 쌍둥이 영웅 우나푸와 스발랑케는 군주들과 공놀이로 겨루고 꾀로 이겨 아버지의 원수를 갚습니다.', false, now(), null),
  ('aztlan', 'fantasy', 'myth', '아스틀란', 'Aztlán', '아즈텍 사람들이 떠나온 백로의 섬', '신대륙 전설', '멕시코 북쪽 어딘가', '16세기 기록', 21.9058, -105.475, '아즈텍(메시카) 사람들이 처음 살았다는 고향으로, 하얀 땅 또는 백로의 땅이라는 뜻으로 풀이합니다. 호수 가운데 섬에서 배를 타고 떠난 이들은 신 우이칠로포치틀리의 인도를 받아 오랫동안 떠돌다가, 선인장 위에서 뱀을 문 독수리를 보고 그 자리에 테노치티틀란을 세웁니다.', false, now(), null),
  ('ys', 'fantasy', 'legend', '이스', 'Ys', '바닷속에 잠긴 브르타뉴의 도시', '켈트·아더왕', '브르타뉴 앞바다', '브르타뉴 전설', 48.0928, -4.3292, '그라들론 왕이 다스렸다는 바닷가의 화려한 도시입니다. 바다를 막는 둑의 수문 열쇠는 왕만 지녔는데, 공주 다위트가 잠든 왕에게서 열쇠를 훔쳐 문을 열면서 도시가 물에 잠깁니다. 왕은 마법의 말을 타고 캥페르로 달아나고, 다위트는 바다의 정령 모르건이 되었다고 전합니다.', false, now(), null),
  ('nirai-kanai', 'fantasy', 'myth', '니라이카나이', 'ニライカナイ', '풍요와 신이 찾아오는 바다 너머의 땅', '동양', '동쪽 바다 너머', '류큐 전승', 26.1578, 127.8867, '오키나와와 아마미의 류큐 전승에서 바다 저편, 해가 뜨는 동쪽이나 바다 밑에 있다고 믿는 이상향입니다. 해마다 신이 이곳에서 찾아와 풍요를 주고 돌아가며, 죽은 이의 혼이 돌아가는 곳이기도 합니다. 창세 신 아마미키요는 니라이카나이에서 건너와 섬을 만들고, 독수리를 보내 벼 이삭을 얻어 왔다고 합니다.', false, now(), null)
insert into public.catalog_courses (id, title, summary, stops, hidden, updated_at, updated_by) values
  ('arthur', '아더왕의 길', '거석의 평원에서 시작해 원탁의 성을 지나 사과의 섬으로 향합니다.', array['stonehenge', 'camelot', 'avalon', 'tir-na-nog']::text[], false, now(), null),
  ('aegean', '에게해의 미궁과 신들', '미궁의 궁전과 신들의 산, 가라앉은 섬의 이야기를 함께 따라갑니다.', array['knossos', 'atlantis', 'acropolis', 'olympus', 'arcadia', 'elysion']::text[], false, now(), null),
  ('gold', '황금을 찾아서', '잉카의 도시에서 출발해 정복자들이 끝내 찾지 못한 황금의 땅을 좇습니다.', array['machu-picchu', 'el-dorado', 'cibola']::text[], false, now(), null),
  ('immortal', '불로불사의 동방', '영원을 꿈꾼 황제의 무덤에서 신선의 섬과 복사꽃 마을로 떠납니다.', array['terracotta', 'penglai', 'peach-blossom', 'kunlun', 'gyeongju']::text[], false, now(), null),
  ('center', '세계의 중심 산', '돌로 지은 우주의 산에서 눈에 보이지 않는 왕국까지 오릅니다.', array['angkor-wat', 'borobudur', 'sumeru', 'shambhala', 'shangri-la']::text[], false, now(), null),
  ('edge', '세상의 끝', '세계의 배꼽이라 불린 섬에서 해가 지지 않는 북쪽 끝까지 갑니다.', array['rapa-nui', 'thule', 'asgard']::text[], false, now(), null),
  ('afterlife', '저승 순례', '갈대의 들판에서 그리스의 명계와 일본의 요미를 지나 마야의 시발바까지 죽은 이들의 길을 따라갑니다.', array['aaru', 'hades', 'valhalla', 'yomi', 'chichen-itza', 'xibalba']::text[], false, now(), null),
  ('paradise', '잃어버린 낙원', '네 강이 흐르던 동산에서 바다 너머 신의 섬까지, 사람들이 그려 온 낙원을 모읍니다.', array['eden', 'dilmun', 'elysion', 'tir-na-nog', 'nirai-kanai']::text[], false, now(), null),
  ('mesoamerica', '아메리카 신들의 길', '백로의 섬을 떠난 메시카의 이주 길을 따라 신들이 태어난 도시와 마야의 저승으로 갑니다.', array['aztlan', 'teotihuacan', 'chichen-itza', 'tikal', 'xibalba']::text[], false, now(), null)
