  ('myth-gate', '신화의 문', '신화 속 장소의 현실 연고지에서 처음 인증했습니다', 'fantasy', '신화 1곳', false, now(), null),
  ('myth-paradise', '낙원을 찾아서', '에덴, 엘리시온, 무릉도원 같은 낙원 3곳에서 인증했습니다', 'fantasy', '낙원 3곳', false, now(), null),
  ('myth-afterlife', '저승 순례자', '하데스의 명계, 요미노쿠니, 시발바 같은 저승 3곳에서 인증했습니다', 'fantasy', '저승 3곳', false, now(), null),
  ('myth-divine', '신들의 거처', '올림포스, 아스가르드, 수미산 같은 신들의 거처 3곳에서 인증했습니다', 'fantasy', '신들의 거처 3곳', false, now(), null),
  ('myth-odyssey', '신화 대모험', '신화 속 장소 10곳에서 인증했습니다', 'fantasy', '신화 10곳', false, now(), null),
  ('course-arthur', '아더왕의 길 완주', '아더왕의 길 코스의 4곳을 모두 인증했습니다', 'real', '코스 4곳', false, now(), null),
  ('course-aegean', '에게해의 미궁과 신들 완주', '에게해의 미궁과 신들 코스의 6곳을 모두 인증했습니다', 'real', '코스 6곳', false, now(), null),
  ('course-gold', '황금을 찾아서 완주', '황금을 찾아서 코스의 3곳을 모두 인증했습니다', 'real', '코스 3곳', false, now(), null),
