-- scripts/export-supabase-seed.mjs가 만든 파일입니다. 손으로 고치지 말고 `pnpm run db:seed:export`로 다시 만듭니다.
-- 원천: apps/admin/src/shared/api/demo/seed.ts(운영 어드민 데모와 같은 목데이터), 앱 카탈로그, src/shared/api/demo-master.ts
-- 회원은 모두 가상이고 비밀번호가 없어 로그인할 수 없습니다(본명은 비움). 관리자 로그인은 docs/supabase-restore.md를 따릅니다.
-- 프로필 사진 파일은 SQL로 넣을 수 없어 `pnpm run db:seed:export -- --avatars <폴더>`로 만든 JPEG를 avatars 버킷에 올립니다.
-- 여러 번 실행해도 됩니다: 카탈로그는 이 내용으로 덮어쓰고, 회원·스탬프·신고는 이미 있으면 건너뜁니다.

begin;

-- 회원(auth.users). 가입 트리거가 profiles를 만들고, 아래에서 닉네임·사진·가입일을 맞춥니다.
on conflict (id) do nothing;

-- 프로필(관리자 보기 admin_users의 원본). 본명(name)은 비웁니다.
on conflict (id) do update set nickname = excluded.nickname, name = excluded.name, avatar_path = excluded.avatar_path, created_at = excluded.created_at, updated_at = excluded.updated_at;

-- 데모 관리자
on conflict (user_id) do nothing;

-- 수록 여행지·코스·뱃지(앱 카탈로그와 같음)
on conflict (id) do update set realm = excluded.realm, lore = excluded.lore, name = excluded.name, original_name = excluded.original_name, tagline = excluded.tagline, group_name = excluded.group_name, location = excluded.location, era = excluded.era, latitude = excluded.latitude, longitude = excluded.longitude, overview = excluded.overview, hidden = excluded.hidden, updated_at = excluded.updated_at, updated_by = excluded.updated_by;

on conflict (id) do update set title = excluded.title, summary = excluded.summary, stops = excluded.stops, hidden = excluded.hidden, updated_at = excluded.updated_at, updated_by = excluded.updated_by;

on conflict (id) do update set name = excluded.name, description = excluded.description, tone = excluded.tone, rule = excluded.rule, hidden = excluded.hidden, updated_at = excluded.updated_at, updated_by = excluded.updated_by;

-- 현장 인증 스탬프
on conflict do nothing;

-- 닉네임·프로필 사진 신고
on conflict (id) do nothing;

commit;
